INSERT INTO site_areas (slug,area_type,country_code,name_ar,name_en,name_fr,currency_code,currency_symbol) VALUES ('malaysia','country','MY','ماليزيا','Malaysia','Malaisie','MYR','RM') ON CONFLICT (slug) DO UPDATE SET name_ar=EXCLUDED.name_ar,name_en=EXCLUDED.name_en,currency_code='MYR',currency_symbol='RM',is_active=TRUE,updated_at=NOW();
INSERT INTO area_content (area_id,content_key,content_ar,content_en,content_type,section,sort_order) SELECT id,v.k,v.ar,v.en,'text',v.s,v.o FROM site_areas JOIN (VALUES ('seo_title','تحفيظ القرآن وتأسيس العربية أونلاين في ماليزيا | أكاديمية الحافظ','Online Quran and Arabic Foundations in Malaysia','seo',0),('seo_description','تحفيظ القرآن الكريم وتأسيس اللغة العربية أونلاين من ماليزيا بحصص فردية وأسعار بالرينغيت الماليزي.','Online Quran memorization and Arabic foundations from Malaysia with individual lessons and MYR prices.','seo',1),('local_card','Al-Hafiz Academy provides individual online Quran memorization and Arabic foundations lessons for Arabic-speaking learners in Malaysia. Kuala Lumpur, George Town, Johor Bahru and Kota Kinabalu are geographic references for this page. Learning is online, communication is in Arabic, and there is no local office, branch or teaching location in Malaysia.','Online Quran memorization and Arabic foundations for Arabic-speaking learners in Malaysia.','local',0)) v(k,ar,en,s,o) ON site_areas.slug='malaysia' ON CONFLICT (area_id,content_key) DO UPDATE SET content_ar=EXCLUDED.content_ar,content_en=EXCLUDED.content_en,is_active=TRUE;
INSERT INTO area_packages (area_id,program,package_key,name_ar,name_en,description_ar,price,currency_code,sessions_per_month,is_active,sort_order) SELECT id,v.p,v.k,v.n,v.n,v.d,v.price,'MYR',v.sessions,TRUE,v.o FROM site_areas JOIN (VALUES ('quran','quran-4','تحفيظ القرآن — 4 حصص','Quran memorization',61,'حفظ ومراجعة فردية',4,0),('quran','quran-8','تحفيظ القرآن — 8 حصص','Quran memorization',114,'حفظ ومراجعة فردية',8,1),('quran','quran-12','تحفيظ القرآن — 12 حصة','Quran memorization',171,'حفظ ومراجعة فردية',12,2),('quran','quran-16','تحفيظ القرآن — 16 حصة','Quran memorization',224,'حفظ ومراجعة فردية',16,3),('arabic','arabic-4','تأسيس العربية — 4 حصص','Arabic foundations',81,'قراءة وفهم',4,0),('arabic','arabic-8','تأسيس العربية — 8 حصص','Arabic foundations',146,'قراءة وفهم',8,1),('arabic','arabic-12','تأسيس العربية — 12 حصة','Arabic foundations',219,'قراءة وفهم',12,2),('arabic','arabic-16','تأسيس العربية — 16 حصة','Arabic foundations',293,'قراءة وفهم',16,3)) v(p,k,n,d,price,description_text,sessions,o) ON site_areas.slug='malaysia' ON CONFLICT (area_id,package_key) DO UPDATE SET price=EXCLUDED.price,name_ar=EXCLUDED.name_ar,program=EXCLUDED.program,is_active=TRUE;
INSERT INTO area_faq_items (area_id,question_key,question_ar,question_en,answer_ar,answer_en,sort_order) SELECT id,v.k,v.q,v.q,v.a,v.a,v.o FROM site_areas JOIN (VALUES ('my-1','كيف تبدأ الدراسة من ماليزيا؟','تبدأ الدراسة أونلاين بذكر الهدف والمستوى والوقت المناسب، ثم تُرتب الحصة التجريبية المجانية.',0),('my-2','هل الأسعار بالرينغيت الماليزي؟','نعم، الأسعار الظاهرة في صفحة ماليزيا بالرينغيت الماليزي.',1),('my-3','ما مدة الحصة الأساسية؟','مدة الحصة الأساسية المعروضة 30 دقيقة.',2),('my-4','بأي لغة يتم التواصل؟','يتم التواصل مع الأكاديمية باللغة العربية.',3),('my-5','هل توجد باقات مخصصة؟','يوجد باقات مخصصة.',4)) v(k,q,a,o) ON site_areas.slug='malaysia' ON CONFLICT (area_id,question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar,answer_ar=EXCLUDED.answer_ar,is_active=TRUE;
INSERT INTO area_links (area_id,link_key,label_ar,label_en,href,link_type,is_external,sort_order) SELECT id,v.k,v.l,v.l,v.h,v.t,v.x,v.o FROM site_areas JOIN (VALUES ('canonical','الصفحة الرسمية','https://quran-elhafez.com/malaysia','canonical',TRUE,0),('whatsapp','واتساب','https://bit.ly/4aJfOl6','external',TRUE,1),('home','الرئيسية','/','internal',FALSE,2),('games','الألعاب والمسابقات','/games','internal',FALSE,3),('library','المكتبة','/library','internal',FALSE,4)) v(k,l,h,t,x,o) ON site_areas.slug='malaysia' ON CONFLICT (area_id,link_key) DO UPDATE SET href=EXCLUDED.href,label_ar=EXCLUDED.label_ar,is_active=TRUE;
INSERT INTO area_themes (area_id,theme_name_ar,theme_name_en,primary_color,secondary_color,accent_color,background_color,text_color) SELECT id,'دفتر ملاحظات ماليزيا','Malaysia school notebook','#047857','#6D28D9','#FDE68A','#FFFEF7','#1F2937' FROM site_areas WHERE slug='malaysia' ON CONFLICT (area_id) DO UPDATE SET primary_color=EXCLUDED.primary_color,secondary_color=EXCLUDED.secondary_color,accent_color=EXCLUDED.accent_color,background_color=EXCLUDED.background_color,text_color=EXCLUDED.text_color,is_active=TRUE;
INSERT INTO area_cities (area_id,city_key,name_ar,name_en,region_name,sort_order) SELECT id,v.k,v.a,v.e,v.r,v.o FROM site_areas JOIN (VALUES ('kuala-lumpur','كوالالمبور','Kuala Lumpur','Kuala Lumpur',10),('george-town','جورج تاون','George Town','Penang',20),('johor-bahru','جوهور باهرو','Johor Bahru','Johor',30),('kota-kinabalu','كوتا كينابالو','Kota Kinabalu','Sabah',40)) v(k,a,e,r,o) ON site_areas.slug='malaysia' ON CONFLICT (area_id,city_key) DO UPDATE SET name_ar=EXCLUDED.name_ar,name_en=EXCLUDED.name_en,is_active=TRUE;
INSERT INTO area_timezones (area_id,timezone_name,label_ar,label_en,is_primary,sort_order) SELECT id,'Asia/Kuala_Lumpur','توقيت ماليزيا (Asia/Kuala_Lumpur)','Malaysia Time',TRUE,10 FROM site_areas WHERE slug='malaysia' ON CONFLICT (area_id,timezone_name) DO UPDATE SET label_ar=EXCLUDED.label_ar,is_primary=TRUE,is_active=TRUE;
